input.command:
mkdir -p "$TMPDIR/check" && cat > "$TMPDIR/check/check.py" <<'EOF'
import csv, sys, os
from datetime import date, timedelta
D = sys.argv[1]
P = date(2026,11,27)
def d(s): return date.fromisoformat(s)
read = {}
def load(name):
    with open(os.path.join(D,name), encoding="utf-8") as f:
        lines = [l for l in f if l.strip() and not l.startswith("#")]
    rows = list(csv.DictReader(lines)); read[name] = len(rows); return rows
con = load("contracts_register_2026.csv"); reg = {r["id"]:r for r in load("registration_M1M2_2026.csv")}
rec = load("employee_records_2026.csv"); att = load("attendance_2026-11.csv")
ot = load("overtime_weekly_2026.csv"); pl = load("payroll_lines_2026-07_to_10.csv")
pr = load("payroll_runs_2026.csv"); lv = {r["id"]:r for r in load("leave_decisions_2026.csv")}
med = load("medical_exams.csv"); tr = {r["id"]:r for r in load("training_proofs_2026.csv")}
ab = load("absences_2026.csv")
txt = {}
for n in ["meldungen_ueberstunden_ordner.txt","sicherheitserklaerung_2019.md","ordner-index.md"]:
    txt[n] = open(os.path.join(D,n),encoding="utf-8").read().splitlines()
F, G = [], []
start = {r["id"]:d(r["start_date"]) for r in con}
# M1/M2
late = [i for i,s in start.items() if i not in reg or d(reg[i]["date_filed"]) > s - timedelta(1)]
F.append(("L02","M1/M2 nicht spätestens am Tag vor Arbeitsbeginn",late,""))
for i,s in start.items():
    if i in reg and 0 <= (s-d(reg[i]["date_filed"])).days <= 3 and i not in late: G.append((i,"M1/M2 knapp vor Arbeitsbeginn"))
# Overtime
over = sorted({r["id"] for r in ot if float(r["overtime_hours"])>8})
F.append(("L05","Überstunden über 8 Std./Woche",over,f'{sum(float(r["overtime_hours"])>8 for r in ot)} Wochen'))
for i in sorted({r["id"] for r in ot if 7<=float(r["overtime_hours"])<=8}): G.append((i,"Überstunden 7 bis 8 Std./Woche, Grenze eingehalten"))
mel = txt["meldungen_ueberstunden_ordner.txt"]
has2026 = any(l.startswith("2026-") for l in mel)
noml = sorted({r["id"] for r in ot if float(r["overtime_hours"])>0}) if not has2026 else []
F.append(("L06","Überstundenwochen ohne Meldung",noml,f'{sum(float(r["overtime_hours"])>0 for r in ot)} Wochen'))
otm = {(r["id"],r["week_start"][:7]) for r in ot if float(r["overtime_hours"])>0}
nol = sorted({r["id"] for r in pl if (r["id"],r["month"]) in otm and r["overtime_line_hours"].strip() in ("","0")})
F.append(("L07","Lohnzeile ohne Überstundenzeile",nol,f'{sum((r["id"],r["month"]) in otm and r["overtime_line_hours"].strip() in ("","0") for r in pl)} Lohnzeilen'))
# Attendance
absd = set()
for a in ab:
    x=d(a["from"])
    while x<=d(a["to"]): absd.add((a["id"],x.isoformat())); x+=timedelta(1)
bad = [r for r in att if (not r["start"] or not r["end"]) and (r["id"],r["date"]) not in absd]
F.append(("L04","Anwesenheit ohne Beginn und Ende",sorted({r["id"] for r in bad}),f"{len(bad)} Tageszeilen"))
exc = [r for r in att if (not r["start"] or not r["end"]) and (r["id"],r["date"]) in absd]
if exc: G.append((exc[0]["id"],f"{len(exc)} leere Tage mit Code ABS, gedeckt durch absences_2026.csv"))
# Pay
lp=[]
for r in pr:
    dl = d(r["period_end"])+timedelta(15)
    while dl.weekday()>=5: dl+=timedelta(1)
    pd = d(r["pay_date"])
    if pd>dl: lp.append(f'{r["period_end"][:7]} ({(pd-dl).days} Tage)')
    elif (dl-pd).days<=1: G.append((r["period_end"][:7],f"Lohn am {pd}, Frist fiel auf Wochenende und verschob auf {dl}"))
F.append(("L08","Lohn später als 15 Tage (Wochenende verschiebt)",lp,""))
# Leave
def plus6(s):
    m=s.month+6; y=s.year+(m-1)//12; m=(m-1)%12+1; return date(y,m,min(s.day,28))
miss=[i for i,s in start.items() if plus6(s)<=P and i not in lv]
low=[i for i in lv if int(lv[i]["days"])<20]
F.append(("L09","Urlaubsbescheid fehlt",miss,"")); F.append(("L09","Urlaubsbescheid unter 20 Tagen",low,""))
for i,s in start.items():
    if plus6(s)>P: G.append((i,f"6 Monate erst am {plus6(s)}, noch kein Bescheid geschuldet"))
for i in lv:
    if int(lv[i]["days"])==20: G.append((i,"Bescheid genau 20 Tage"))
# Records
emp=[(r["id"],k) for r in rec for k in r if k!="id" and not r[k].strip()]
F.append(("L03","Leere Felder in der Akte",sorted({i for i,_ in emp}),f"{len(emp)} Felder"))
# Medical
lim=date(2024,11,27)
old=[r["id"] for r in med if d(r["last_exam_date"])<lim]
F.append(("L12","Untersuchung älter als 24 Monate",old,""))
for r in med:
    x=d(r["last_exam_date"])
    if lim<=x<=lim+timedelta(31): G.append((r["id"],f"Untersuchung {x}, knapp unter 24 Monaten"))
# Safety statement
se=[l[2:].strip() for l in txt["sicherheitserklaerung_2019.md"] if l.startswith("- ")]
roles=sorted({r["role"] for r in con}); mr=[x for x in roles if x not in se]
F.append(("L10","Stellenbezeichnung fehlt in Sicherheitserklärung",mr,f'{sum(r["role"] in mr for r in con)} Personen betroffen'))
# Training
new=[i for i,s in start.items() if P-timedelta(365)<=s<=P]
lt=[i for i in new if i not in tr or d(tr[i]["training_date"])>start[i]]
F.append(("L13","Unterweisung fehlt oder später als Einstellungstag",lt,f"{len(new)} Neueinstellungen geprüft"))
for i in new:
    if i in tr and tr[i]["training_date"]==start[i].isoformat(): G.append((i,"Unterweisung am Einstellungstag"))
print("GELESEN", read, {k:len([l for l in v if l.strip()]) for k,v in txt.items()})
for f in F: print("FUND" if f[2] else "OK", f[0], f[1], len(f[2]), ",".join(f[2]), f[3])
for g in G: print("GRENZ", *g)
print("SUMME", sum(read.values()), sum(1 for f in F if f[2]), len(G))
EOF
python3 -I "$TMPDIR/check/check.py" "$PWD"
